		#region 获取目录所有文本文件 
	    private List<string> GetTextFiles(string dir)
	    {
			string[] files = Directory.GetFiles(dir, "*.xlsx");	

	        List<string> strList = new List<string>(files);//files.ToList();
			List<string> strRemove = new List<string>();
			
			try
			{
				for (int i = strList.Count-1 ; i>= 0; i--)
		        {
		            if (strList[i].IndexOf("_已读") != -1)
		            {
						strRemove.Add(strList[i].ToString());
		                continue;
		            }
		            FileInfo fi = new FileInfo(strList[i]);
		            int dtDiff = DateTime.Compare(fi.CreationTime,DateTime.Now.AddMinutes(-1d));
					// 近10秒内生成的文件， 暂不处理
		            if (dtDiff > 0)
		            {
						strRemove.Add(strList[i].ToString());
		                continue;
		            }
		        }
				
//				foreach(string vRemove in strRemove)
//				{
//					strList.Remove(vRemove);
//				}
			}
	        catch (Exception ex)
	        {
				aTimer.Stop();
				IsRunning=false;
	            MessageBox.Show(ex.Message);
				Scripter.MESTxnPanel.Controls["btn_BtnStop"].Text = "启用同步";
	        }
	        return strList;	      
	    }
