				/// <summary>
		/// 读取 Excell 文件数据
		/// </summary>
		/// <param name="filepath">本地文件路径</param>
		/// <returns></returns>
		private DataSet ReadExcelData(string fileUrl,string sheetName)
        {
			DataSet ds = new DataSet();
			
            try
            {
                string st =Path.GetExtension(fileUrl);
                string strForRe = "";

                if (st == ".xls")
                {
                    strForRe = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source= " + fileUrl + ";Extended Properties='Excel 8.0;HDR=Yes;IMEX=1'";
                }
                else if (st == ".xlsx")
                {
                    strForRe = "Provider=Microsoft.Ace.OLEDB.12.0;Data Source= " + fileUrl + ";Extended Properties='Excel 8.0;HDR=Yes;IMEX=1'";
                }

                OleDbConnection connection = new OleDbConnection(strForRe);

                connection.Open();

                System.Data.DataTable table = connection.GetOleDbSchemaTable(System.Data.OleDb.OleDbSchemaGuid.Tables, null);

                string str2 = "SELECT * FROM [" + sheetName + "]";

                OleDbDataAdapter adapter = new OleDbDataAdapter(str2, connection);

                adapter.Fill(ds, "DataSet");
                connection.Close();
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
            }
			
			return ds;
        }
		
       	/// <summary>
		/// 获取 Excell 工作表
		/// </summary>
		/// <param name="filepath">本地文件路径</param>
		/// <returns></returns>
		private System.Data.DataTable GetExcelSheetName(string fileUrl)
        {
			System.Data.DataTable tb=new System.Data.DataTable();
			
			try  
            {  
                string st = st = Path.GetExtension(fileUrl);
                string strForRe = "";

                if (st == ".xls")
                {
                    strForRe = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source= " + fileUrl + ";Extended Properties='Excel 8.0;HDR=Yes;IMEX=1'";
                }
                else if (st == ".xlsx")
                {
                    strForRe = "Provider=Microsoft.Ace.OLEDB.12.0;Data Source= " + fileUrl + ";Extended Properties='Excel 8.0;HDR=Yes;IMEX=1'";
                }

                OleDbConnection connection = new OleDbConnection(strForRe);

                connection.Open();

               	tb = connection.GetOleDbSchemaTable(System.Data.OleDb.OleDbSchemaGuid.Tables, null);
				
				//移除多余列
				if(tb.Columns.Count>0)
				{
					for(int i=0;i<tb.Columns.Count;i++)
					{
						if(Convert.ToString(tb.Columns[i].ColumnName)!="TABLE_NAME")
						{
							tb.Columns.Remove(Convert.ToString(tb.Columns[i].ColumnName));
						}
					}
					
					//移出多余的列
					tb=TableRemoveCol(tb);
				}
			
				//移除多余行
				if(tb.Rows.Count>0)
				{
					for(int i=0;i<tb.Rows.Count;i++)
					{
						if(Convert.ToString(tb.Rows[i][0]).Contains("Print_Titles")||
							Convert.ToString(tb.Rows[i][0]).Contains("Print_Area"))
						{						
							tb.Rows.RemoveAt(i);
						}
					}
				}
				
				connection.Close();
           	}  
           	catch(Exception ex)
           	{
				MessageBox.Show(ex.Message);
			}
			
			return tb;
		}
		
		/// <summary>
		/// 移出 SheetName 多余列
		/// </summary>
		/// <param name="filepath">DataTable</param>
		/// <returns></returns>
		public System.Data.DataTable TableRemoveCol(System.Data.DataTable tb)
        {
            if (tb.Columns.Count > 1)
            {
                for (int i = 0; i < tb.Columns.Count; i++)
                {
                    if (Convert.ToString(tb.Columns[i].ColumnName) != "TABLE_NAME")
                    {
                        tb.Columns.Remove(Convert.ToString(tb.Columns[i].ColumnName));

						//递归移出多余列
                        TableRemoveCol(tb);
                    }
                }
            }
			
			return tb;
        }
		
		/// <summary>
		/// 导入生产信息表数据
		/// </summary>
		/// <param name="xmlData">XMl 内容</param>
		/// <returns></returns>
		public int ImportData(string xmlData,ref string returnMessage,string ButtonName)
        {
		
			string columnName="";
			DataSet ds=new DataSet();
				titleStr="";
				columnName="";
				//读取 Excel 工作表数据
				ds=ReadExcelData(Scripter.GetParameterValue("FileUrl"),Scripter.GetParameterValue("SheetName"));
			
//			if (ds.Tables["DataSet"].Columns.Count == 60)
			{
				int result=-1;
				returnMessage="";
				ButtonName="";
				
				string I_OrBitUserId=Scripter.OrBitUserId;
				string I_ResourceId=Scripter.ResourceId;
				string SyncGUID=Guid.NewGuid().ToString();	
	            string FuncName=Scripter.GetParameterValue("FuncName");
				string ScheduleNo=Scripter.GetParameterValue("ScheduleNo");
				string TableName=Scripter.GetParameterValue("TableName");
				string SheetName=Scripter.GetParameterValue("SheetName").Replace("'","");
				string LineCount=Scripter.GetParameterValue("LineCount");
				xmlData = xmlData.Replace("'","''");
			
				try
				{
				string str=@"DECLARE @return_value int,
									 @I_ReturnMessage nvarchar(max)							
						EXEC @return_value = [dbo].[ImportExcelCommonDoMethod]
							@I_ReturnMessage = @I_ReturnMessage output ,
							@I_OrBitUserId = N'"+I_OrBitUserId+@"',
							@I_ResourceId = N'"+I_ResourceId+@"',		
							@SyncGUID=N'"+SyncGUID+@"',	
							@DocNo=N'"+ScheduleNo+@"',	
							@FuncName=N'"+FuncName+@"',	
							@TableName=N'"+TableName+@"',
							@SheetName=N'"+SheetName+@"',
							@LineCount="+LineCount+@",
							@XMlData=N'"+xmlData+@"'
					
						select @I_ReturnMessage as N'I_ReturnMessage',@return_value as N'return_value' ";				
					//执行 SQL 语句
					DataSet dss=Scripter.GetSqlDataSet(str);
					
					returnMessage=Convert.ToString(dss.Tables[0].Rows[0]["I_ReturnMessage"]);
					
					if(Convert.ToString(dss.Tables[0].Rows[0]["return_value"])=="-1")
					{
						result=-1;
					}
					else
					{
						result=0;
					}
				}
				catch(Exception ex)
				{
					returnMessage=ex.ToString();
				}
				
				return result;
			}
			
			
			
			return 0;
		}
       
